import sys

def compute_lps(pattern):
    n = len(pattern)
    lps = [0] * n
    length = 0
    i = 1

    while i < n:
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1

    return lps

def can_be_repeated(s):
    n = len(s)
    if n <= 1:
        return False

    lps = compute_lps(s)
    max_lps = lps[-1]

    if max_lps == 0:
        return False

    period = n - max_lps

    if period < n and n % period == 0:
        return True

    return False

def main():
    s = sys.stdin.readline().strip()

    if can_be_repeated(s):
        print("NO")
    else:
        print("YES")

if __name__ == "__main__":
    main()
